import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, convert, formatMoney, RATES } from '../src/money.js';

test('roundCents rounds half to even', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
  assert.equal(roundCents(2.4), 2);
  assert.equal(roundCents(2.6), 3);
  assert.equal(roundCents(-0.5), 0);
});

test('roundCents ignores binary noise', () => {
  assert.equal(roundCents(0.1 * 3 * 100), 30);
  assert.equal(roundCents(1.005 * 100), 100);
});

test('formatEuros adds the sign, thousands separators and two decimals', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
  assert.equal(formatEuros(5), '€0.05');
  assert.equal(formatEuros(-250), '-€2.50');
  assert.equal(formatEuros(100000000), '€1,000,000.00');
});

test('parseEuros reads what people type', () => {
  assert.deepEqual(parseEuros('12'), { ok: true, value: 1200 });
  assert.deepEqual(parseEuros('12.5'), { ok: true, value: 1250 });
  assert.deepEqual(parseEuros('1,234.56'), { ok: true, value: 123456 });
  assert.deepEqual(parseEuros('12.345'), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(parseEuros('abc'), { ok: false, error: 'AMOUNT_INVALID' });
});

test('RATES has correct values', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to USD', () => {
  // 100 EUR cents = 1 EUR = 1.085 USD = 108.5 USD cents → 108 or 109
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  // 10000 * 1.085 = 10850
  assert.equal(result.value, 10850);
});

test('convert EUR to GBP', () => {
  // 100 EUR cents = 1 EUR = 0.8425 GBP = 84.25 GBP cents → 84
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  // 10000 * 0.8425 = 8425
  assert.equal(result.value, 8425);
});

test('convert EUR to EUR', () => {
  const result = convert(10000, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10000);
});

test('convert rejects unknown currency', () => {
  const result = convert(10000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert with fractional cents rounds correctly', () => {
  // 123 EUR cents * 1.085 = 133.455 → rounds to 133
  const result = convert(123, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 133);
});

test('convert handles negative amounts', () => {
  const result = convert(-10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, -10850);
});

test('convert zero amount', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert large amounts', () => {
  // 1 million EUR cents = 10000 EUR
  const result = convert(1000000, 'USD');
  assert.equal(result.ok, true);
  // 1000000 * 1.085 = 1085000
  assert.equal(result.value, 1085000);
});

test('formatMoney formats EUR', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
  assert.equal(formatMoney(5, 'EUR'), '€0.05');
  assert.equal(formatMoney(-250, 'EUR'), '-€2.50');
});

test('formatMoney formats USD', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
  assert.equal(formatMoney(5, 'USD'), '$0.05');
  assert.equal(formatMoney(-250, 'USD'), '-$2.50');
});

test('formatMoney formats GBP', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
  assert.equal(formatMoney(5, 'GBP'), '£0.05');
  assert.equal(formatMoney(-250, 'GBP'), '-£2.50');
});

test('formatMoney with large amounts', () => {
  assert.equal(formatMoney(100000000, 'USD'), '$1,000,000.00');
  assert.equal(formatMoney(100000000, 'GBP'), '£1,000,000.00');
});

test('formatMoney with zero', () => {
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
  assert.equal(formatMoney(0, 'USD'), '$0.00');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
});

test('convert and formatMoney work together', () => {
  const eurCents = 123456;
  const usdResult = convert(eurCents, 'USD');
  const formatted = formatMoney(usdResult.value, 'USD');
  // 123456 * 1.085 = 133,979.76 → roundCents → 133,980
  assert.equal(formatted, '$1,339.80');
});

